 *
 * This test verifies that a new user can successfully register with a unique,
 * valid email and strong password, and that all required session context
 * metadata is included. The response should return all required fields
 * including UUID, email, create/update timestamps, and valid JWT tokens with
 * expiration info. All returned data is asserted by typia, and business context
 * fields are checked for realistic business values. This test does not interact
 * with the database directly, only validates API and DTO contract.
 */
export async function test_api_user_registration_with_valid_data(
  connection: api.IConnection,
) {
  // Prepare valid registration body
  const registration = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    href: "https://app.todo.example.com/register", // Valid example registration page
    referrer: "https://app.todo.example.com/landing", // Valid example referral page
    ip: typia.random<string & tags.Format<"ipv4">>(), // Optionally provided by client
  } satisfies ITodoListUser.ICreate;

  // Call registration API
  const result = await api.functional.auth.user.join(connection, {
    body: registration,
  });
  typia.assert(result);

  // Business-level result assertion: input email matches output
  TestValidator.equals(
    "registered email matches input",
    result.email,
    registration.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates that attempting to register with an email address already in use is
 * properly rejected.
 *
 * This test creates a user (with a valid, random email and all required
 * registration properties), then attempts to register another account using the
 * same email but a new password and new URIs. The first registration must
 * succeed and issue tokens; the second should fail with a business
 * logic/restriction error (duplicate email). No type errors or schema
 * violations are tested, only business logic correctness.
 */
export async function test_api_user_registration_with_duplicate_email(
  connection: api.IConnection,
) {
  // Create test user registration input
  const email = typia.random<string & tags.Format<"email">>();
  const password1 = typia.random<string & tags.Format<"password">>();
  const href1 = "https://example.com/register";
  const referrer1 = "https://google.com";

  // Step 1: Register the user for the first time (should succeed)
  const registered: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email,
        password: password1,
        href: href1,
        referrer: referrer1,
      } satisfies ITodoListUser.ICreate,
    });
  typia.assert(registered);
  TestValidator.equals(
    "first registration email matches",
    registered.email,
    email,
  );
  TestValidator.predicate(
    "access token must be string",
    typeof registered.token.access === "string",
  );
  TestValidator.predicate(
    "refresh token must be string",
    typeof registered.token.refresh === "string",
  );
  TestValidator.predicate(
    "access token expires at is ISO date string",
    typeof registered.token.expired_at === "string",
  );
  TestValidator.predicate(
    "refresh token refreshable until is ISO date string",
    typeof registered.token.refreshable_until === "string",
  );

  // Step 2: Attempt duplicate registration (should fail)
  const password2 = typia.random<string & tags.Format<"password">>();
  const href2 = "https://example.com/new-registration";
  const referrer2 = "https://bing.com";

  await TestValidator.error(
    "duplicate email registration is rejected",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          email, // same email as previous
          password: password2,
          href: href2,
          referrer: referrer2,
        } satisfies ITodoListUser.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate user login with correct credentials.
 *
 * 1. Generate unique, valid registration data (email, password, URIs).
 * 2. Register user via api.functional.auth.user.join.
 * 3. Login using same email and password with /auth/user/login.
 * 4. Ensure login succeeds, response type is ITodoListUser.IAuthorized, and JWT
 *    tokens/access metadata are included and valid.
 * 5. Assert login user matches registered user email.
 */
export async function test_api_user_login_with_valid_credentials(
  connection: api.IConnection,
) {
  // 1. Generate registration data
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const href = "https://test-client.app/join";
  const referrer = "https://search-engine.test/";

  // 2. Register user
  const joinOutput: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email,
        password: password as string & tags.Format<"password">,
        href,
        referrer,
        ip: null,
      } satisfies ITodoListUser.ICreate,
    });
  typia.assert(joinOutput);
  TestValidator.equals(
    "registered email matches input",
    joinOutput.email,
    email,
  );

  // 3. Login with same valid credentials
  const loginHref = "https://test-client.app/login";
  const loginReferrer = href;
  const loginResp: ITodoListUser.IAuthorized =
    await api.functional.auth.user.login(connection, {
      body: {
        email,
        password,
        href: loginHref,
        referrer: loginReferrer,
        ip: null,
      } satisfies ITodoListUser.ILogin,
    });
  typia.assert(loginResp);

  // 4. Assert JWT tokens present and correct type
  TestValidator.predicate(
    "access token exists",
    typeof loginResp.token.access === "string" &&
      loginResp.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token exists",
    typeof loginResp.token.refresh === "string" &&
      loginResp.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token expiration present",
    typeof loginResp.token.expired_at === "string" &&
      loginResp.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshable_until timestamp present",
    typeof loginResp.token.refreshable_until === "string" &&
      loginResp.token.refreshable_until.length > 0,
  );

  // 5. Validate login user matches registered email
  TestValidator.equals(
    "login email matches registered email",
    loginResp.email,
    email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
